import {
  myQuestionList,
  questionList,
  questionDoneList,
  hasten,
  listDemand,
  questionDelete,
  processCreate,
  questionSubmit,
  getNextUser,
  questionSend
} from "@/api/ictOperation/index"
import operateForm from './operateForm'
import solveForm from './solveForm'
import questionDetailForm from './questionDetailForm'
import xtTreeLzaySelect from "@/components/xtTreeLzaySelect/index.vue";
import { getDictList } from "@/api/dict";
import questionForm from './questionForm';
import {mapGetters,mapState} from "vuex";

export default {
  components: { operateForm, questionDetailForm, questionForm, solveForm, xtTreeLzaySelect },
  data() {
    return{
      typeList: [],
      statusList: [
        {
          dictKey: '0',
          dictValue: '已提交'
        },
        {
          dictKey: '1',
          dictValue: '处理中'
        },
        {
          dictKey: '2',
          dictValue: '已解决'
        },
        {
          dictKey: '3',
          dictValue: '纳入需求'
        },
      ],

      isEdit: false,
      isJiejue: false,
      listApi: myQuestionList,
      searchForm: {
        deptId: undefined,
        deptName: undefined,
        type: undefined,
        status: undefined,
        current: 1,
        size: 20
      },
      questionData: [],
      total: 0,
      tableLoading: false,
      questionId: '',
      showOperate: false,
      showSolve: false,
      showDetail: false,
      showUpdateForm: false,

    }
  },
  computed: {
    ...mapGetters(["permission", "userDetail"]),
    permissionList() {
      return {
        questionTodo: this.vaildData(this.permission.question_todo, false),
        questionDone: this.vaildData(this.permission.question_done, false),
      };
    },
    isRoleAlias(){
      return this.$store.state.user.userDetail.roleAlias.includes('control_solver')
    }
  },
  mounted() {
    this.getDict()
    this.getList()
  },
  methods: {
    getEntityUnit(val) {
      //选择单位 部门
      this.searchForm.deptId = val.id
      this.searchForm.deptName = val.fullName
      this.$refs.searchForm.$forceUpdate()
      this.$forceUpdate()
    },
    handleSearch(){
      this.getList()
    },
    handleExport() {
      //导出
      let types1 = {
        '0': "我的问题",
        '1': "待办任务",
        '2': "已办任务",
        '3': "需求",
      }
      let types2 = {
        '0': "my",
        '1': "todo",
        '2': "done",
        '3': "demand",
      }


      this.$confirm("是否导出数据?", "提示", {
        confirmButtonText: "确定",
        cancelButtonText: "取消",
        type: "warning"
      }).then(() => {
        this.download(
          "/api/idevelop-control/question/download/exportNew",
          this.searchForm,
          "全部问题.xlsx"
        )
      });

    },

    // 字典值
    getDict() {
      let dict = ['control_question_type']
      for(let i=0; i<dict.length; i++) {
        getDictList(dict[i]).then(res => {
          if(dict[i] == 'control_question_type') { //问题类型
            this.typeList = res.data
          }
        })
      }
    },

    getList() {
      // this.tableLoading = true
      // this.listApi(this.searchForm).then(res => {
      //   this.questionData = res.data.records
      //   this.total = res.data.total
      //   this.tableLoading = false
      // })

      this.tableLoading = true
      questionList(this.searchForm).then(res => {
        this.questionData = res.data.records
        this.total = res.data.total
        this.tableLoading = false 
      })
    },
    handleClick(tabs) {
      this.listApi = myQuestionList
      this.getList()
    },
    // seeDetail(row) {
    //   this.questionId = row.id
    //   if(row.status == 0) {
    //     this.showUpdateForm = true
    //   }else {
    //     this.showDetail = true
    //   }
    // },

    seeDetail(row, isJiejue) {
      this.questionId = row.id
      if(row.status == 0) {
        this.showUpdateForm = true
      }else {
        this.isJiejue = isJiejue
        this.showDetail = true
      }
    },



    handleEdit(row){
      // this.isEdit = true
      this.questionId = row.id
      this.showUpdateForm = true
    },
    async handleOperate(row) {
      if(row.status == 0) {
        let createRes = await processCreate({id: row.id})
      }
      this.questionId = row.id

      if(this.isRoleAlias){ // 处理人
        this.showOperate = true
      }else{ // 提报人
        questionSubmit({
          userName: this.userDetail.userName,
          comment: "问题提交",
          id: row.id
        }).then(res => {
          this.submitProcess()
        })
      } 
    },

    async handleSolve(row) {
      this.questionId = row.id
      this.showSolve = true
    },


    delOrder(row) {
      this.$confirm('确定删除该问题?', '提示', {
        confirmButtonText: '确定',
        cancelButtonText: '取消',
        type: 'warning'
      }).then(() => {
        questionDelete({id: row.id}).then(() => {
          this.$message({
            message: '删除成功！',
            type: 'success'
          });
          this.getList()
        })
      })
    },

    cancel() {
      this.$emit('backQuestion')
    },
    submitProcess() {
      this.showOperate = false
      this.showSolve = false
      this.$message({
        message: '处理成功！',
        type: 'success'
      });
      this.getList()
    },
    typeFormatter(row) {
      return this.selectDictLabel(this.typeList, row.type)
    },
    isResolveFormatter(row){
      if(row.isResolve == 1){
        return '已解决'
      }else{
        return '未解决'
      }
    },
    backQuestion() {
      this.showUpdateForm = false
      this.getList()
    }
  }
}
